{"command":"cat > /tmp/eval_diff.py << 'PY'
import json
data=json.load(open("/tmp/diff_data.json"))

def segs_from_events(events):
    # events: list of ('eq',char_tgt),('del',char_src),('ins',char_tgt)
    segs=[]
    prev=None
    for typ,ch in events:
        if typ=='del':
            prev=None
            continue
        color='32' if typ=='eq' else '1;31'
        if prev==typ and segs:
            segs[-1]=(color, segs[-1][1]+ch)
        else:
            segs.append((color,ch))
        prev=typ
    return segs

def lcs_events(a,b,tie='del',direction='forward'):
    # dp suffix LCS
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if a[i]==b[j]: dp[i][j]=1+dp[i+1][j+1]
            else: dp[i][j]=max(dp[i+1][j],dp[i][j+1])
    ev=[]
    if direction=='forward':
        i=j=0
        while i<n and j<m:
            if a[i]==b[j]:
                ev.append(('eq',b[j])); i+=1; j+=1
            elif dp[i+1][j] > dp[i][j+1] or (dp[i+1][j]==dp[i][j+1] and tie=='del'):
                ev.append(('del',a[i])); i+=1
            else:
                ev.append(('ins',b[j])); j+=1
        while i<n: ev.append(('del',a[i])); i+=1
        while j<m: ev.append(('ins',b[j])); j+=1
    else: # backward walk from end, then reverse
        rev=[]
        i=n; j=m
        # dp prefix
        # compute prefix dp
        # instead use suffix dp above but moving backward: if a[i-1]==b[j-1] eq else compare dp[i-1][j] vs dp[i][j-1] ??? dp here suffix not helpful
        # compute prefix LCS table
        pref=[[0]*(m+1) for _ in range(n+1)]
        for ii in range(n):
            for jj in range(m):
                if a[ii]==b[jj]: pref[ii+1][jj+1]=pref[ii][jj]+1
                else: pref[ii+1][jj+1]=max(pref[ii][jj+1],pref[ii+1][jj])
        while i>0 and j>0:
            if a[i-1]==b[j-1]:
                rev.append(('eq',b[j-1])); i-=1; j-=1
            elif pref[i-1][j] > pref[i][j-1] or (pref[i-1][j]==pref[i][j-1] and tie=='del'):
                rev.append(('del',a[i-1])); i-=1
            else:
                rev.append(('ins',b[j-1])); j-=1
        while i>0: rev.append(('del',a[i-1])); i-=1
        while j>0: rev.append(('ins',b[j-1])); j-=1
        ev=list(reversed(rev))
    return ev

def difflib_events(a,b):
    import difflib
    sm=difflib.SequenceMatcher(a=a,b=b,autojunk=False)
    ev=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=='equal':
            for k in range(j1,j2): ev.append(('eq',b[k]))
        elif tag=='delete':
            for k in range(i1,i2): ev.append(('del',a[k]))
        elif tag=='insert':
            for k in range(j1,j2): ev.append(('ins',b[k]))
        elif tag=='replace':
            for k in range(i1,i2): ev.append(('del',a[k]))
            for k in range(j1,j2): ev.append(('ins',b[k]))
    return ev

def prefix_suffix_events(a,b):
    # common prefix/suffix
    i=0
    while i<min(len(a),len(b)) and a[i]==b[i]: i+=1
    j=0
    while j<min(len(a)-i,len(b)-i) and a[-1-j]==b[-1-j]: j+=1
    ev=[]
    for k in range(i): ev.append(('eq',b[k]))
    # middle: delete then insert
    for k in range(i,len(a)-j): ev.append(('del',a[k]))
    for k in range(i,len(b)-j): ev.append(('ins',b[k]))
    for k in range(len(b)-j,len(b)): ev.append(('eq',b[k]))
    return ev

candidates={
 "lcs_fwd_del": lambda a,b: lcs_events(a,b,'del','forward'),
 "lcs_fwd_ins": lambda a,b: lcs_events(a,b,'ins','forward'),
 "lcs_back_del": lambda a,b: lcs_events(a,b,'del','backward'),
 "lcs_back_ins": lambda a,b: lcs_events(a,b,'ins','backward'),
 "difflib": difflib_events,
 "prefix_suffix": prefix_suffix_events,
}
for name,fn in candidates.items():
    ok=0; total=len(data)
    examples=[]
    for d in data:
        pred=[tuple(x) for x in segs_from_events(fn(d['src'],d['tgt']))]
        obs=[tuple(x) for x in d['segs']]
        if pred==obs: ok+=1
        elif len(examples)<5:
            examples.append((d['src'],d['tgt'],obs,pred))
    print(name, ok, "/", total)
    for e in examples: print(" ",e)
