use std::fs;
fn encode_segs(segs: Vec<(String,String)>)->String{
    segs.iter().map(|(c,t)| format!("{}:{}",c,t)).collect::<Vec<_>>().join("|")
}
fn segs_from_diff_results(results: Vec<diff::Result<char>>, swapped: bool)->Vec<(String,String)>{
    // results from diff::chars(x,y) where if swapped x=tgt y=src
    // Classification: Both green, char in tgt only red, char in src only = del breaker
    let mut segs: Vec<(String,String)> = Vec::new();
    let mut prev: Option<String> = None; // "eq" or "ins"
    for r in results {
        let (typ, ch_opt) = match r {
            diff::Result::Both(c,_) => ("eq", Some(c)),
            diff::Result::Left(c) => { if swapped { ("ins", Some(c)) } else { ("del", None::<char>) } },
            diff::Result::Right(c) => { if swapped { ("del", None::<char>) } else { ("ins", Some(c)) } },
        };
        // Actually Left/Right chars: need char value when it's ins side; above we lost for some? Left c captured, Right c captured but in del branch we set None. Fix by reconstructing below
        let _ = ch_opt;
        if typ=="del" { prev=None; continue; }
        let ch = match r {
            diff::Result::Both(c,_)=>c,
            diff::Result::Left(c)=>c,
            diff::Result::Right(c)=>c,
        };
        let color = if typ=="eq" {"32"} else {"1;31"};
        if prev.as_deref()==Some(typ) {
            if let Some(last)=segs.last_mut(){ last.1.push(ch); }
        } else {
            segs.push((color.to_string(), ch.to_string()));
        }
        prev=Some(typ.to_string());
    }
    segs
}
fn main(){
    let content=fs::read_to_string("/tmp/pairs.tsv").unwrap();
    for line in content.lines(){
        let mut it=line.split('\t');
        let a=it.next().unwrap(); let b=it.next().unwrap();
        // diff fwd
        let fwd=segs_from_diff_results(diff::chars(a,b), false);
        let swp=segs_from_diff_results(diff::chars(b,a), true);
        // difflib
        let mut preds_difflib: Vec<(String,String)> = Vec::new();
        {
            use difflib::sequencematcher::{SequenceMatcher, get_opcodes};
            // difflib crate API: SequenceMatcher::new(a_chars,b_chars) ??
            let a_chars: Vec<char>=a.chars().collect();
            let b_chars: Vec<char>=b.chars().collect();
            let opcodes=get_opcodes(&a_chars, &b_chars);
            let mut prev: Option<String>=None;
            for op in opcodes {
                // op: (tag, i1,i2,j1,j2) type? We'll handle in code below after compile discovery
                let _ = op;
            }
            let _ = preds_difflib;
        }
        println!("{}\t{}\t{}\t{}", a,b, encode_segs(fwd), encode_segs(swp));
    }
}
