import json, sys
sys.setrecursionlimit(10000)
data=json.load(open("/tmp/diff_data.json"))
def segs_from_events(events):
    segs=[]; prev=None
    for typ,ch in events:
        if typ=='del': prev=None; continue
        color='32' if typ=='eq' else '1;31'
        if prev==typ and segs: segs[-1]=(color,segs[-1][1]+ch)
        else: segs.append((color,ch))
        prev=typ
    return segs

def lcs_len_row(a,b):
    # return row where row[j]=LCS(a, b[:j])
    prev=[0]*(len(b)+1)
    for ca in a:
        cur=[0]*(len(b)+1)
        for j,cb in enumerate(b,1):
            cur[j]=prev[j-1]+1 if ca==cb else max(prev[j],cur[j-1])
        prev=cur
    return prev

def hirsch_lcs_pairs(a,b,choose='min'):
    # return list of (i,j) matches using Hirschberg on a
    if not a or not b:
        return []
    if len(a)==1:
        # if char in b, match first occurrence? or ?
        # standard base: if a in b return...
        if a[0] in b:
            # choose ? first
            j=b.index(a[0]) if choose=='min' else len(b)-1-b[::-1].index(a[0])
            return [(0,j)]
        else:
            return []
    mid=len(a)//2
    left=lcs_len_row(a[:mid], b)
    # right: LCS of reversed a[mid:] and reversed b
    right=lcs_len_row(a[mid:][::-1], b[::-1]) # right[k]=LCS(a[mid:], b[len - k:])? need index: right_rev[j'] where j' is suffix length
    # total for split at j: left[j] + LCS(a[mid:], b[j:]) . LCS(a[mid:], b[j:]) = right[len(b)-j]
    best=None; bestj=0
    candidates=range(len(b)+1)
    if choose!='min': candidates=list(reversed(candidates))
    for j in candidates:
        val=left[j]+right[len(b)-j]
        if best is None or val>best:
            best=val; bestj=j
    pairs=[]
    for i,j in hirsch_lcs_pairs(a[:mid], b[:bestj], choose):
        pairs.append((i,j))
    for i,j in hirsch_lcs_pairs(a[mid:], b[bestj:], choose):
        pairs.append((i+mid, j+bestj))
    return pairs

def events_from_pairs(a,b,pairs):
    ev=[]; i=j=0
    for mi,mj in pairs:
        while i<mi: ev.append(('del',a[i])); i+=1
        while j<mj: ev.append(('ins',b[j])); j+=1
        ev.append(('eq',b[j])); i+=1; j+=1
    while i<len(a): ev.append(('del',a[i])); i+=1
    while j<len(b): ev.append(('ins',b[j])); j+=1
    return ev

