                pairs=hirsch_lcs_pairs(d['tgt'],d['src'],choose)
                pairs=[(j,i) for i,j in pairs] # pairs (src idx, tgt idx?) Wait hirsch args (tgt,src) returns (tgt_idx, src_idx), swap back
