import json, sys
sys.setrecursionlimit(10000)
data=json.load(open("/tmp/diff_data.json"))
def segs_from_events(events):
    segs=[]; prev=None
    for typ,ch in events:
        if typ=='del': prev=None; continue
        color='32' if typ=='eq' else '1;31'
        if prev==typ and segs: segs[-1]=(color,segs[-1][1]+ch)
        else: segs.append((color,ch))
        prev=typ
    return segs

def find_middle_snake(a,b):
    N=len(a); M=len(b)
    delta=N-M
    MAX=(N+M+1)//2  # ceil?
    vf={1:0}
    vb_rev={1:0}
    vb_orig={delta:N}  # start point
    for d in range(MAX+1):
        # forward
        new_vf={}
        for k in range(-d, d+1, 2):
            if k==-d or (k!=d and vf.get(k-1, -10**9) < vf.get(k+1, -10**9)):
                x=vf.get(k+1,0)
            else:
                x=vf.get(k-1,0)+1
            y=x-k
            xs,ys=x,y
            while x<N and y<M and a[x]==b[y]:
                x+=1; y+=1
            new_vf[k]=x
            if delta%2!=0 and k in vb_orig and x>=vb_orig[k]:
                return (xs,ys,x,y)
        vf=new_vf
        # backward
        new_vb={}
        for kr in range(-d, d+1, 2):
            if kr==-d or (kr!=d and vb_rev.get(kr-1, -10**9) < vb_rev.get(kr+1, -10**9)):
                p=vb_rev.get(kr+1,0)
            else:
                p=vb_rev.get(kr-1,0)+1
            q=p-kr
            ps,qs=p,q
            while p<N and q<M and a[N-p-1]==b[M-q-1]:
                p+=1; q+=1
            new_vb[kr]=p
            k_orig=delta-kr
            X_low=N-p; Y_low=M-q; X_high=N-ps; Y_high=M-qs
            if delta%2==0 and k_orig in vf and X_low <= vf[k_orig]:
                return (X_low, Y_low, X_high, Y_high)
        vb_rev=new_vb
        vb_orig={delta-kr: N-p for kr,p in vb_rev.items()}
    # fallback: whole ?
    return (0,0,0,0)

def conquer(a,b):
    # return events for strings a,b
    if not a:
        return [('ins',c) for c in b]
    if not b:
        return [('del',c) for c in a]
    if a==b:
        return [('eq',c) for c in a]
    xs,ys,xe,ye=find_middle_snake(a,b)
    # snake is equal segment a[xs:xe]==b[ys:ye]; ensure
