    def base_ev(a,b):
        if base=='forward': return myers_events(a,b,'down')
        else:
            raw=myers_events(b,a,'down')
            ev=[]
            for typ,ch in raw:
                if typ=='eq': ev.append(('eq',ch))
                elif typ=='del': ev.append(('ins',ch))
                else: ev.append(('del',ch))
            return ev
    def diff(a,b):
        if not a: return [('ins',c) for c in b]
        if not b: return [('del',c) for c in a]
        if a==b: return [('eq',c) for c in a]
        ev=base_ev(a,b)
        edits=sum(1 for t,_ in ev if t!='eq')
        if edits<=1 or (len(a)+len(b))<=base_limit:
            return ev
        pts=events_pos(a,b,ev)
        # find splitting index
        if mode.startswith('edit'):
            target = edits//2 if mode=='edit_floor' else (edits+1)//2
            # walk events accumulating edits, find first index (event position) where edits cum == target, then include subsequent eq as snake
            cum=0; idx=0
            for idx,(typ,ch) in enumerate(ev):
                if cum>=target: break
                if typ!='eq': cum+=1
            else:
                idx=len(ev)
            # idx is first event index (?) Position before ev[idx]
            xs,ys=pts[idx]
            # snake = eq run starting idx
            xe,ye=xs,ys; k=idx
            while k<len(ev) and ev[k][0]=='eq':
                xe+=1; ye+=1; k+=1
        elif mode.startswith('step'):
            target=(len(a)+len(b))//2
            idx=min(target, len(ev))
            xs,ys=pts[idx]; xe,ye=xs,ys; k=idx
            while k<len(ev) and ev[k][0]=='eq': xe+=1; ye+=1; k+=1
        # avoid no progress
        if (xs==0 and ys==0 and xe==0 and ye==0) or (xs==len(a) and ys==len(b)) or (xe==len(a) and ye==len(b) and xs==0 and ys==0 and k==len(ev)):
            return ev
        if (xs==0 and ys==0 and xe==0 and ye==0) or (xe==len(a) and ye==len(b) and (xs!=0 or ys!=0) and False):
            return ev
        left = diff(a[:xs], b[:ys]) if (xs or ys) else []
        mid=[('eq',c) for c in b[ys:ye]]
        right= diff(a[xe:], b[ye:]) if (xe<len(a) or ye<len(b)) else []
        # validate progress: if left+right same size recursion? subtasks are smaller in at least one dimension unless snake empty and split at boundary extremes
        if (xs,ys,xe,ye)==(0,0,0,0) or (xs,ys,xe,ye)==(len(a),len(b),len(a),len(b)):
            return ev
        return left+mid+right
    return diff

