use std::collections::HashMap;
use std::sync::OnceLock;

static TABLE_DATA: &str = include_str!("deunicode_data.txt");

fn table() -> &'static HashMap<char, &'static str> {
    static TABLE: OnceLock<HashMap<char, &'static str>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut map = HashMap::new();
        for line in TABLE_DATA.lines() {
            if let Some((cp, value)) = line.split_once('\t') {
                if let Ok(num) = cp.parse::<u32>() {
                    if let Some(ch) = char::from_u32(num) {
                        map.insert(ch, value);
                    }
                }
            }
        }
        map
    })
}

/// Convert a string to a plain ASCII representation, closely following
/// the behaviour exposed by the tool for non-ASCII input. ASCII text is
/// passed through unchanged, except for `/`, which becomes `_`.
pub fn deunicode(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    for ch in input.chars() {
        if ch == '/' {
            output.push('_');
        } else if ch.is_ascii() {
            output.push(ch);
        } else if let Some(replacement) = table().get(&ch) {
            // A replacement may itself contain a slash for a handful of
            // characters; those are normalised in the same way.
            for c in replacement.chars() {
                if c == '/' {
                    output.push('_');
                } else {
                    output.push(c);
                }
            }
        }
    }
    output
}
