use crate::operation::Operation;
use crate::output::{red};
use std::fmt;
use std::path::PathBuf;

#[derive(Debug)]
pub enum Error {
    BadExpression(regex::Error),
    ConflictWithExistingPath(Operation),
    FilesWillHaveSameName(String),
    CannotSolveSortingProblem,
    CannotRename(Operation, std::io::Error),
    CannotOpenReadFile(PathBuf),
    CannotParseJsonFile(PathBuf),
    CannotCreateFile(PathBuf),
    CannotCreateBackup(PathBuf),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::BadExpression(err) => {
                write!(f, "Bad expression provided\n\n{}", red(&err.to_string()))
            }
            Error::ConflictWithExistingPath(op) => write!(
                f,
                "Conflict with existing path {}",
                red(&format!("{} -> {}", op.source.display(), op.target.display()))
            ),
            Error::FilesWillHaveSameName(duplicates) => write!(
                f,
                "Files will have the same name\n{}",
                red(duplicates)
            ),
            Error::CannotSolveSortingProblem => {
                write!(f, "Cannot solve sorting problem.{}", red(""))
            }
            Error::CannotRename(op, err) => write!(
                f,
                "Cannot rename {}",
                red(&format!(
                    "{} -> {}\n{}",
                    op.source.display(),
                    op.target.display(),
                    err
                ))
            ),
            Error::CannotOpenReadFile(path) => write!(
                f,
                "Cannot open/read file {}",
                red(&path.display().to_string())
            ),
            Error::CannotParseJsonFile(path) => write!(
                f,
                "Cannot parse JSON file {}",
                red(&path.display().to_string())
            ),
            Error::CannotCreateFile(path) => {
                write!(f, "Cannot create file {}", red(&path.display().to_string()))
            }
            Error::CannotCreateBackup(path) => write!(
                f,
                "Cannot create a backup of {}",
                red(&path.display().to_string())
            ),
        }
    }
}

impl std::error::Error for Error {}
