#[derive(Debug, Clone, PartialEq, Eq)]
enum DiffEvent {
    Equal(char),
    // Character present only in the target name.
    Added(char),
    // Character present only in the source name.
    Removed,
}

fn myers_events(a: &[char], b: &[char]) -> Vec<DiffEvent> {
    // The classic O(ND) Myers algorithm, storing the trace of V arrays so
    // the edit path can be reconstructed by walking it backwards.
    let n = a.len() as isize;
    let m = b.len() as isize;
    if n == 0 {
        return b.iter().map(|_| DiffEvent::Removed).collect();
    }
    if m == 0 {
        return a.iter().map(|c| DiffEvent::Added(*c)).collect();
    }
    let max = (n + m) as usize;
    let offset = (max + 2) as isize;
    let width = 2 * max + 5;
    let idx = |k: isize| -> usize { (k + offset) as usize };
    let mut trace: Vec<Vec<isize>> = Vec::new();
    let mut v = vec![0isize; width];
    let mut final_d = 0usize;
    'outer: for d in 0..=max {
        trace.push(v.clone());
        let d_i = d as isize;
        let mut k = -d_i;
        while k <= d_i {
            let mut x = if k == -d_i || (k != d_i && v[idx(k - 1)] < v[idx(k + 1)]) {
                v[idx(k + 1)]
            } else {
                v[idx(k - 1)] + 1
            };
            let mut y = x - k;
            while x < n && y < m && a[x as usize] == b[y as usize] {
                x += 1;
                y += 1;
            }
            v[idx(k)] = x;
            if x >= n && y >= m {
                final_d = d;
                break 'outer;
            }
            k += 2;
        }
    }
    let _ = final_d;
    let mut events_rev: Vec<DiffEvent> = Vec::new();
    let mut x = n;
    let mut y = m;
    for d in (1..trace.len()).rev() {
        let d_i = d as isize;
        let v_prev = &trace[d];
        let k = x - y;
        let prev_k = if k == -d_i || (k != d_i && v_prev[idx(k - 1)] < v_prev[idx(k + 1)]) {
            k + 1
        } else {
            k - 1
        };
        let prev_x = v_prev[idx(prev_k)];
        let prev_y = prev_x - prev_k;
        while x > prev_x && y > prev_y {
            events_rev.push(DiffEvent::Equal(b[(y - 1) as usize]));
            x -= 1;
            y -= 1;
        }
        if x == prev_x {
            // Insertion into `a` (only in source when a is the target).
            events_rev.push(DiffEvent::Removed);
            y -= 1;
        } else {
            events_rev.push(DiffEvent::Added(a[(x - 1) as usize]));
            x -= 1;
        }
    }
    while x > 0 && y > 0 {
        events_rev.push(DiffEvent::Equal(b[(y - 1) as usize]));
        x -= 1;
        y -= 1;
    }
    events_rev.reverse();
    events_rev
}

fn colored_diff(source_name: &str, target_name: &str) -> String {
    // Diff the target (first sequence) against the source (second
    // sequence): characters unique to the target are additions, while
    // characters unique to the source act as separators.
    let target_chars: Vec<char> = target_name.chars().collect();
    let source_chars: Vec<char> = source_name.chars().collect();
    let events = myers_events(&target_chars, &source_chars);
    let mut output = String::new();
    let mut current_kind: Option<bool> = None; // true = added, false = equal
    let mut current = String::new();
    let mut flush = |kind: Option<bool>, text: &str, out: &mut String| {
        if text.is_empty() {
            return;
        }
        match kind {
            Some(true) => out.push_str(&bold_red(text)),
            Some(false) => out.push_str(&green(text)),
            None => {}
        }
    };
    for event in events {
        match event {
            DiffEvent::Equal(c) => {
                if current_kind != Some(false) {
                    flush(current_kind, &current, &mut output);
                    current.clear();
                    current_kind = Some(false);
                }
                current.push(c);
            }
            DiffEvent::Added(c) => {
                if current_kind != Some(true) {
                    flush(current_kind, &current, &mut output);
                    current.clear();
                    current_kind = Some(true);
                }
                current.push(c);
            }
            DiffEvent::Removed => {
                flush(current_kind, &current, &mut output);
                current.clear();
                current_kind = None;
            }
        }
    }
    flush(current_kind, &current, &mut output);
    output
}

pub fn format_operation(operation: &Operation) -> String {
    let source_parent = operation.source.parent().unwrap().to_str().unwrap();
    let source_file_name = operation.source.file_name().unwrap().to_str().unwrap();
    let target_parent = operation.target.parent().unwrap().to_str().unwrap();
    let target_file_name = operation.target.file_name().unwrap().to_str().unwrap();
    let source = if source_parent.is_empty() {
        grey(source_file_name)
    } else {
