            grey(source_file_name)
        )
    };
    let target_parent_part = if target_parent.is_empty() {
        String::new()
    } else {
        green(&format!("{}/", target_parent))
    };
    format!(
        "{} -> {}{}",
        source,
        target_parent_part,
        colored_diff(source_file_name, target_file_name)
    )
}
