use crate::error::Error;
use crate::operation::Operation;
use serde::{Deserialize, Serialize};
use std::fs::File;
use std::path::{Path, PathBuf};

#[derive(Debug, Serialize, Deserialize)]
pub struct Dump {
    pub date: String,
    pub operations: Vec<Operation>,
}

pub fn create_dump(operations: &[Operation], dump_prefix: &str) -> Result<(), Error> {
    let now = chrono::Local::now();
    let filename = format!("{}{}.json", dump_prefix, now.format("%Y-%m-%d_%H%M%S"));
    let dump = Dump {
        date: now.format("%Y-%m-%d %H:%M:%S").to_string(),
        operations: operations.to_vec(),
    };
    let content = serde_json::to_string_pretty(&dump).unwrap_or_default();
    std::fs::write(&filename, content)
        .map_err(|_| Error::CannotCreateFile(PathBuf::from(filename)))
}

pub fn read_dump(path: &Path) -> Result<Dump, Error> {
    let file = File::open(path)
        .map_err(|_| Error::CannotOpenReadFile(path.to_path_buf()))?;
    serde_json::from_reader(file)
        .map_err(|_| Error::CannotParseJsonFile(path.to_path_buf()))
}
