use crate::dump::create_dump;
use crate::error::Error;
use crate::operation::Operation;
use crate::output::{red, Printer};
use std::collections::{HashMap, HashSet};
use std::path::PathBuf;

pub struct RenamerSettings {
    pub force: bool,
    pub backup: bool,
    pub silent: bool,
    pub dump: bool,
    pub dump_prefix: String,
    pub no_dump: bool,
}

impl RenamerSettings {
    pub fn dry_run(&self) -> bool {
        !self.force
    }
    fn should_dump(&self) -> bool {
        (self.force || self.dump) && !self.no_dump
    }
}

fn check_duplicates(operations: &HashMap<PathBuf, PathBuf>) -> Result<(), Error> {
    let mut sorted: Vec<(&PathBuf, &PathBuf)> = operations.iter().collect();
    sorted.sort_by(|a, b| a.0.cmp(b.0));
    let mut seen: HashMap<&PathBuf, &PathBuf> = HashMap::new();
    let mut duplicates: Vec<String> = Vec::new();
    for (source, target) in sorted {
        if let Some(first_source) = seen.get(target) {
            duplicates.push(
                red(&format!(
                    "\n{}->{}\n{}->{}\n",
                    first_source.display(),
                    target.display(),
                    source.display(),
                    target.display()
                ))
                .to_string(),
            );
        } else {
            seen.insert(target, source);
        }
    }
    if duplicates.is_empty() {
        Ok(())
    } else {
        Err(Error::FilesWillHaveSameName(duplicates.concat()))
    }
}

fn check_existing(operations: &HashMap<PathBuf, PathBuf>) -> Result<(), Error> {
    for (source, target) in operations.iter() {
        if !operations.contains_key(target)
            && target.symlink_metadata().is_ok()
        {
            return Err(Error::ConflictWithExistingPath(Operation::new(
                source.clone(),
                target.clone(),
            )));
        }
    }
    Ok(())
}

fn sort_operations(
    operations: &HashMap<PathBuf, PathBuf>,
) -> Result<Vec<Operation>, Error> {
    let mut remaining: Vec<Operation> = operations
        .iter()
        .map(|(s, t)| Operation::new(s.clone(), t.clone()))
        .collect();
    // Deepest paths first, so contents of a directory are renamed before
    // the directory itself. The sort is stable, preserving the map order
    // among paths of the same depth.
    remaining.sort_by(|a, b| {
        b.source
            .ancestors()
            .count()
            .cmp(&a.source.ancestors().count())
    });
    let mut sorted = Vec::new();
    while !remaining.is_empty() {
        let index = remaining.iter().position(|op| {
            !remaining
                .iter()
                .any(|other| other.source == op.target)
