        dump: common.dump,
        dump_prefix: common.dump_prefix.clone(),
        no_dump: common.no_dump,
    }
}

fn is_hidden(entry: &walkdir::DirEntry) -> bool {
    entry
        .file_name()
        .to_str()
        .map(|name| name.starts_with('.'))
        .unwrap_or(false)
}

