    paths: &[String],
    traversal: &TraversalOptions,
    solver: &dyn Solver,
) -> HashMap<PathBuf, PathBuf> {
    let mut operations: HashMap<PathBuf, PathBuf> = HashMap::new();
    let max_depth = if traversal.recursive {
        traversal.max_depth.unwrap_or(usize::MAX)
    } else {
        0
    };
