        let walker = WalkDir::new(path).max_depth(max_depth).into_iter();
        let include_hidden = traversal.hidden;
        let walker = walker.filter_entry(move |entry| {
            include_hidden || entry.depth() == 0 || !is_hidden(entry)
        });
