                Err(err) => {
                    printer.print_error(&err);
                    return 1;
                }
            };
            let mut operations = loaded.operations;
            if args.undo {
                operations = operations
                    .into_iter()
                    .rev()
                    .map(|op| Operation::new(op.target, op.source))
                    .collect();
            }
            renamer::process_loaded_operations(operations, &settings, &printer)
        }
        Commands::ToAscii(args) => {
            configure_color(args.common.color);
            let solver = ToAsciiSolver;
            let operations = collect_operations(&args.paths, &args.traversal, &solver);
            renamer::process_operations(operations, &settings_from(&args.common))
        }
    }
}

fn main() {
    std::process::exit(run());
}
