def greedy(a,b,search_a=True):
    ev=[]; i=j=0
    while i<len(a) and j<len(b):
        if a[i]==b[j]:
            ev.append(('eq',b[j])); i+=1; j+=1
        elif search_a and a[i] in b[j+1:]:
            ev.append(('ins',b[j])); j+=1
        elif not search_a and b[j] in a[i+1:]:
            ev.append(('del',a[i])); i+=1
        elif search_a:
