use crate::deunicode::deunicode;
use crate::error::Error;
use regex::{Captures, Regex};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReplaceTransform {
    Upper,
    Lower,
    Ascii,
}

impl ReplaceTransform {
    fn apply(&self, text: String) -> String {
        match self {
            ReplaceTransform::Upper => text.to_uppercase(),
            ReplaceTransform::Lower => text.to_lowercase(),
            ReplaceTransform::Ascii => deunicode(&text),
        }
    }
}

pub trait Solver {
    fn solve(&self, file_name: &str) -> String;
}

pub struct RegexSolver {
    expression: Regex,
    replacement: String,
    limit: usize,
    transform: Option<ReplaceTransform>,
}

impl RegexSolver {
    pub fn new(
        expression: &str,
        replacement: &str,
        limit: usize,
        transform: Option<ReplaceTransform>,
    ) -> Result<Self, Error> {
        let expression = Regex::new(expression).map_err(Error::BadExpression)?;
        Ok(RegexSolver {
            expression,
            replacement: replacement.to_string(),
            limit,
            transform,
        })
    }
}

impl Solver for RegexSolver {
    fn solve(&self, file_name: &str) -> String {
        let replacement = self.replacement.clone();
        let transform = self.transform;
        self.expression
            .replacen(file_name, self.limit, |caps: &Captures<'_>| {
                let mut expanded = String::new();
                caps.expand(&replacement, &mut expanded);
                match transform {
                    Some(transform) => transform.apply(expanded),
                    None => expanded,
                }
            })
            .into_owned()
    }
}

pub struct ToAsciiSolver;

impl Solver for ToAsciiSolver {
    fn solve(&self, file_name: &str) -> String {
        deunicode(file_name)
    }
}
