        for k in range(-D, D+1, 2):
            if D==0: x=0
            elif k==-D: x=prev[k+1]
            elif k==D: x=prev[k-1]+1
            else: x=prev[k+1] if prev[k-1] < prev[k+1] else prev[k-1]+1
            y=x-k; xs,ys=x,y
            while x<N and y<M and a[x]==b[y]: x+=1; y+=1
            new[k]=x; snakes[k]=(xs,ys,x,y)
        return new,snakes
    def find(a,b):
