            # backward step on reversed strings, D steps
            Vr_new,snakes_r=forward_step(Vr,N,M,ar,br,D) if D>0 or True else ({}, {})
            # Actually for D=0, forward_step with prev=Vr initial {0:0} gives p=0 then snake backward from end.
